package com.tuap.backend.auth;
import java.security.SecureRandom; import java.time.*; import java.util.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import com.tuap.backend.dominio.entidades.*; import com.tuap.backend.persistencia.*;
@Service public class ReauthenticationService {
 private static final SecureRandom RANDOM=new SecureRandom(); private final ReauthenticationTokenDAO tokens; private final AuthIdentityDAO identities; private final IdentityResolver users; private final ClienteDAO clientes; private final EntrenadorDAO entrenadores; private final PasswordEncoder passwords; private final ReauthenticationProperties properties; private final Clock clock;
 @org.springframework.beans.factory.annotation.Autowired public ReauthenticationService(ReauthenticationTokenDAO t,AuthIdentityDAO i,IdentityResolver u,ClienteDAO c,EntrenadorDAO e,PasswordEncoder p,ReauthenticationProperties x){this(t,i,u,c,e,p,x,Clock.systemUTC());}
 ReauthenticationService(ReauthenticationTokenDAO t,AuthIdentityDAO i,IdentityResolver u,ClienteDAO c,EntrenadorDAO e,PasswordEncoder p,ReauthenticationProperties x,Clock k){tokens=t;identities=i;users=u;clientes=c;entrenadores=e;passwords=p;properties=x;clock=k;}
 @Transactional public ReauthTokenResponse password(AuthenticatedUser user,String password,AuthProvider target){validateTarget(target);requireActive(user);if(!identities.existsByUserIdAndRoleAndProviderAndActiveTrue(user.userId(),user.role(),AuthProvider.LOCAL))throw new LocalIdentityNotAvailableException();String stored=user.role()==Role.CLIENTE?clientes.findById(user.userId()).map(Cliente::getContrasena).orElse(null):entrenadores.findById(user.userId()).map(Entrenador::getContrasena).orElse(null);if(stored==null||password==null||!passwords.matches(password,stored))throw new org.springframework.security.authentication.BadCredentialsException("invalid");return issue(user,target);}
 @Transactional public ReauthTokenResponse provider(AuthenticatedUser user,VerifiedSocialIdentity verified,AuthProvider target){validateTarget(target);requireActive(user);if(verified.provider()==target)throw new InvalidReauthenticationTokenException();AuthIdentity identity=identities.findByProviderAndProviderSubject(verified.provider(),verified.providerSubject()).orElseThrow(InvalidReauthenticationTokenException::new);if(!identity.isActive()||!identity.getUserId().equals(user.userId())||identity.getRole()!=user.role())throw new InvalidReauthenticationTokenException();return issue(user,target);}
 @Transactional public void consumeForUnlink(AuthenticatedUser user,AuthProvider target,String raw){if(raw==null||raw.isBlank())throw new InvalidReauthenticationTokenException();ReauthenticationToken token=tokens.findLockedByTokenHash(PasswordResetService.hash(raw)).orElseThrow(InvalidReauthenticationTokenException::new);if(!token.isUsableAt(clock.instant())||!token.getUserId().equals(user.userId())||token.getRole()!=user.role()||token.getTargetProvider()!=target)throw new InvalidReauthenticationTokenException();token.consume(clock.instant());}
 private ReauthTokenResponse issue(AuthenticatedUser user,AuthProvider target){byte[] bytes=new byte[32];RANDOM.nextBytes(bytes);String raw=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);Instant now=clock.instant();tokens.save(new ReauthenticationToken(PasswordResetService.hash(raw),user.userId(),user.role(),target,now,now.plus(Duration.ofMinutes(properties.getTtlMinutes()))));return new ReauthTokenResponse(raw,Duration.ofMinutes(properties.getTtlMinutes()).toSeconds());}
 private void requireActive(AuthenticatedUser user){if(user==null||users.findByIdAndRole(user.userId(),user.role()).isEmpty())throw new AccountInactiveException();}
 private void validateTarget(AuthProvider target){if(target!=AuthProvider.GOOGLE&&target!=AuthProvider.APPLE)throw new InvalidReauthenticationTokenException();}
}
